{
  "title": "The Glass Diver's Rescue",
  "scenes": [
    {
      "scene_number": 1,
      "caption": "The ruined city gates loom ahead.",
      "visual_description": "Massive iron gates hang crookedly, rusted and overgrown with thorny vines. Faded royal banners flutter weakly in the wind.",
      "characters": ["glass_diver", "mara_the_cartographer"]
    },
    {
      "scene_number": 2,
      "caption": "Mara consults her map at the gate's shadow.",
      "visual_description": "Mara unrolls a stained parchment map under a flickering oil lamp, tracing a route with her inked finger.",
      "characters": ["mara_the_cartographer", "oracle_lamp"]
    },
    {
      "scene_number": 3,
      "caption": "The Oracle Lamp warns of a cursed tower.",
      "visual_description": "The oracle lamp's single eye glows bright orange as it speaks, casting jagged shadows on a crumbling stone wall.",
      "characters": ["oracle_lamp", "glass_diver"]
    },
    {
      "scene_number": 4,
      "caption": "A clockwork fox scouts ahead.",
      "visual_description": "The tin fox darts between rubble piles, its blue glass eyes scanning, key-wind tail twitching silently.",
      "characters": ["tin_fox"]
    },
    {
      "scene_number": 5,
      "caption": "Narrow alleys lead deeper into the city.",
      "visual_description": "Twisting alleyways lined with broken windows and fallen stone, moonlight filtering through shattered rooftops.",
      "characters": ["glass_diver", "mara_the_cartographer"]
    },
    {
      "scene_number": 6,
      "caption": "The sleeping tax collector blocks a doorway.",
      "visual_description": "A dozing figure slumped against a ledger-stacked desk, papers stamped on sleeves, snoring softly amid the ruins.",
      "characters": ["sleeping_tax_collector"]
    },
    {
      "scene_number": 7,
      "caption": "Armored patrols march near the central square.",
      "visual_description": "A column of armored figures in tarnished plate mail clanks across a cracked plaza, their visors down, weapons drawn.",
      "characters": ["mara_the_cartographer", "tin_fox"]
    },
    {
      "scene_number": 8,
      "caption": "The glass diver swims through a magic mirror.",
      "visual_description": "A tall, ornate mirror ripples like water as the glass diver presses through it, helmet reflecting the distorted city.",
      "characters": ["glass_diver"]
    },
    {
      "scene_number": 9,
      "caption": "Inside the cursed tower's entrance hall.",
      "visual_description": "A circular hall with glowing runes on the floor and a spiral staircase ascending into darkness.",
      "characters": ["glass_diver", "oracle_lamp"]
    },
    {
      "scene_number": 10,
      "caption": "The oracle lamp reveals a trap on the stairs.",
      "visual_description": "The lamp's eye flickers red as it illuminates a step that seems solid but is actually a pressure plate over a pit.",
      "characters": ["oracle_lamp", "glass_diver"]
    },
    {
      "scene_number": 11,
      "caption": "Mara finds a hidden passage on her map.",
      "visual_description": "Mara traces a faint line on the map, then presses a stone that slides open, revealing a dark corridor.",
      "characters": ["mara_the_cartographer", "tin_fox"]
    },
    {
      "scene_number": 12,
      "caption": "The tin fox triggers a spring-loaded door.",
      "visual_description": "The fox's tiny foot hits a trigger plate; a hidden door swings open with a clatter, revealing a treasure room.",
      "characters": ["tin_fox"]
    },
    {
      "scene_number": 13,
      "caption": "The sleeping tax collector wakes briefly.",
      "visual_description": "He stirs, blinks at the intruders, stamps a random paper, then falls back asleep on his ledger pillow.",
      "characters": ["sleeping_tax_collector", "glass_diver"]
    },
    {
      "scene_number": 14,
      "caption": "Chased by armored patrols through a courtyard.",
      "visual_description": "The party runs across a broken fountain, clattering armor echoing behind them as patrols close in.",
      "characters": ["glass_diver", "mara_the_cartographer", "tin_fox"]
    },
    {
      "scene_number": 15,
      "caption": "The glass diver dives through a window to escape.",
      "visual_description": "He leaps through a stained-glass window, shattering into a cascade of colored shards, reappearing on the other side.",
      "characters": ["glass_diver"]
    },
    {
      "scene_number": 16,
      "caption": "The final bridge appears ahead.",
      "visual_description": "A long stone bridge arches over a dark chasm, its far end shrouded in mist, broken lanterns lining the edge.",
      "characters": ["mara_the_cartographer", "glass_diver", "oracle_lamp", "tin_fox"]
    },
    {
      "scene_number": 17,
      "caption": "Crossing the bridge under fire.",
      "visual_description": "Arrows and bolts fly from the city behind them as the group races across, the oracle lamp bobbing and the tin fox dodging.",
      "characters": ["glass_diver", "mara_the_cartographer", "oracle_lamp", "tin_fox"]
    },
    {
      "scene_number": 18,
      "caption": "Escape into the night beyond the bridge.",
      "visual_description": "The group reaches the far side, panting, as the ruined city recedes into darkness, the bridge collapsing behind them.",
      "characters": ["glass_diver", "mara_the_cartographer", "oracle_lamp", "tin_fox", "sleeping_tax_collector"]
    }
  ]
}

